thf-loading-icon .thf-loading-icon-container {
  display: flex;
  justify-content: center;
  align-items: center;
}

thf-loading-icon .thf-loading-icon-container.thf-loading-svg-xs {
  width: 1rem;
  height: 1rem;
}
thf-loading-icon .thf-loading-icon-container.thf-loading-svg-sm {
  width: 1.5rem;
  height: 1.5rem;
}
thf-loading-icon .thf-loading-icon-container.thf-loading-svg-md {
  width: 2rem;
  height: 2rem;
}
thf-loading-icon .thf-loading-icon-container.thf-loading-svg-lg {
  width: 5rem;
  height: 5rem;
}

thf-loading-icon .thf-loading-icon-container {
  background-image: url('data:image/gif;base64,');
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
}
:root[class*='-dark'] thf-loading-icon .thf-loading-icon-container {
  background-image: url('data:image/gif;base64,');
}
